// Non-secret settings from whatsapp.configurations + per-request values from the webhook.
// Secrets (tokens, keys) are NOT here: they live in n8n credentials.
const cfg = $input.first().json.cfg ?? {};

const REQUIRED = ['graph_version', 'supabase_url', 'media_bucket'];
const bad = REQUIRED.filter(k => !cfg[k] || cfg[k] === 'CHANGE_ME');
if (bad.length) throw new Error(`Missing config in whatsapp.configurations: ${bad.join(', ')}`);

const value = $('Webhook').first().json.body?.entry?.[0]?.changes?.[0]?.value;

return [{
  json: {
    ...cfg,
    supabase_url: cfg.supabase_url.replace(/\/+$/, ''),
    phone_number_id: value?.metadata?.phone_number_id ?? null,
  },
  pairedItem: { item: 0 },
}];

const value = $('Webhook').first().json.body?.entry?.[0]?.changes?.[0]?.value;
if (!value?.messages?.length) return [];

const contacts = value.contacts ?? [];
const isBsuid = v => /^[A-Z]{2}\./.test(v ?? '');   // BSUID looks like EG.1139891858712101
const MEDIA = ['image', 'audio', 'video', 'document', 'sticker'];

// Meta can batch several messages in one webhook → one item per message
return value.messages.map(msg => {
  const contact = contacts.find(c => c.wa_id === msg.from || (c.user_id && c.user_id === msg.from_user_id)) ?? contacts[0];

  const phone   = !isBsuid(msg.from) ? msg.from : (!isBsuid(contact?.wa_id) ? contact?.wa_id : null) ?? null;
  const user_id = msg.from_user_id ?? contact?.user_id ?? (isBsuid(msg.from) ? msg.from : null);

  const media = MEDIA.includes(msg.type) ? msg[msg.type] : null;
  const loc   = msg.type === 'location' ? msg.location : null;

  // what the user actually wrote (text body or media caption)
  const content = msg.type === 'text' ? (msg.text?.body ?? null) : (media?.caption ?? null);

  // type-specific extras → payload (jsonb)
  let payload = null;
  if (loc) payload = { latitude: loc.latitude, longitude: loc.longitude, name: loc.name ?? null, address: loc.address ?? null, maps_link: `https://www.google.com/maps?q=${loc.latitude},${loc.longitude}` };
  if (msg.type === 'reaction') payload = { emoji: msg.reaction?.emoji ?? null, reacted_to: msg.reaction?.message_id ?? null };
  if (msg.type === 'contacts') payload = { contacts: msg.contacts };
  if (msg.type === 'audio') payload = { voice: msg.audio?.voice ?? null };

  return { json: {
    phone_number_id: value.metadata.phone_number_id,
    phone, user_id,
    reply_to: phone ?? user_id,            // always reply to this
    username: contact?.profile?.username ?? null,
    name: contact?.profile?.name ?? contact?.profile?.username ?? '',
    message_id: msg.id,
    timestamp: Number(msg.timestamp),
    type: msg.type,
    content,
    caption: media?.caption ?? null,
    button_reply: msg.button?.payload ?? msg.interactive?.button_reply?.id ?? msg.interactive?.list_reply?.id ?? null,
    button_title: msg.button?.text ?? msg.interactive?.button_reply?.title ?? msg.interactive?.list_reply?.title ?? null,
    reply_to_message_id: msg.context?.id ?? null,
    media_id: media?.id ?? null,
    media_mime_type: media?.mime_type ?? null,
    media_filename: media?.filename ?? null,
    media_sha256: media?.sha256 ?? null,
    payload,
  } };
});

const value = $('Webhook').first().json.body?.entry?.[0]?.changes?.[0]?.value;
const statuses = value?.statuses ?? [];
const contacts = value?.contacts ?? [];

// Meta can send several statuses in one webhook → one item per status
return statuses.map(s => {
  const contact = contacts.find(c => c.user_id === s.recipient_user_id) ?? contacts[0];

  return {
    json: {
      wamid: s.id,
      status: s.status,                 // sent | delivered | read | played | failed
      timestamp: Number(s.timestamp),
      recipient: s.recipient_id,        // phone (or BSUID if phone is hidden)
      user_id: s.recipient_user_id ?? contact?.user_id ?? null,   // BSUID
      username: contact?.profile?.username ?? null,
      error: s.errors?.[0]
        ? `${s.errors[0].code}: ${s.errors[0].title}${s.errors[0].error_data?.details ? ' — ' + s.errors[0].error_data.details : ''}`
        : null,
    }
  };
});
